export function elNinoSvg(lang, kind, mobile = false) {
  if (!['fr','en'].includes(lang) || !EL_NINO_KINDS.includes(kind) || typeof mobile !== 'boolean') {
    throw new TypeError('Unknown El Nino figure variant');
  }
  return FIGURES[`${kind}-${lang}-${mobile ? 'mobile' : 'desktop'}`];
}
